import sys
from collections import deque

def check_lucky(num):
    """Check if a number is lucky (contains only digits 4 and 7)."""
    while num > 0:
        digit = num % 10
        if digit != 4 and digit != 7:
            return False
        num //= 10
    return True

def find_components(n, edges):
    """Find connected components and their sizes using BFS."""
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = [i]
            visited[i] = True
            while queue:
                u = queue.pop()
                size += 1
                for v in edges[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            components.append(size)

    return components

def compute_father(nodes, edges):
    """Compute component representatives (parent for union-find)."""
    parent = {node: node for node in nodes}

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v

    for u, v in edges:
        union(u, v)

    # Group nodes by representative
    comp_groups = {}
    for node in nodes:
        root = find(node)
        comp_groups.setdefault(root, []).append(node)

    return comp_groups

