    found_cycles = []
    representative_used = set()

    def find_cycles_from(start):
        nonlocal found_cycles
        if len(found_cycles) >= k:
            return

        stack = [(start, {start}, [start], start)]

        while stack:
            root, visited, path, node = stack.pop()

            if len(found_cycles) >= k:
                return

            for neighbor in adj[node]:
                if neighbor == root and len(path) >= 3:
                    if len(path) % 3 != 0 and root not in representative_used:
                        found_cycles.append(path + [root])
                        representative_used.add(root)
                elif neighbor not in visited:
                    stack.append((root, visited | {neighbor}, path + [neighbor], neighbor))

    for i in range(1, n + 1):
        if len(found_cycles) >= k:
            break
        find_cycles_from(i)

    if len(found_cycles) >= k:
        result = sorted(found_cycles, key=lambda x: x[0])[:k]
        lines = ["CYCLES"]
        for cyc in result:
            lines.append(str(len(cyc)))
            lines.append(' '.join(map(str, cyc)))
        return '\n'.join(lines)

    # Find longest path
    best_path = []

    for start in range(1, n + 1):
        visited = set()
        stack = [start]
        parent = {start: -1}
        path = [start]

        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            for neighbor in adj[u]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = u
                    path.append(neighbor)
                    stack.append(neighbor)

        if len(path) > len(best_path):
            best_path = path[::-1]

    target = n / k
    if len(best_path) >= target:
        lines = ["PATH", str(len(best_path)), ' '.join(map(str, best_path))]
        return '\n'.join(lines)

    return "PATH\n1" + '\n' + ' '.join(map(str, list(range(1, min(5, n)+1))))
