4. Output the arrangement and move count

Key insight:
- Two divisors are NOT coprime if they share at least one prime factor
- For n's divisors, I can connect them in a sequence where each consecutive pair shares a prime factor of n
- This minimizes or eliminates the need for LCM insertions

```python
from math import gcd

def solve(n):
    # Get all divisors > 1
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i > 1 and i not in divs:
                divs.append(i)
            if i * i != n and n // i > 1 and n // i not in divs:
                divs.append(n // i)
    divs.sort()

    if len(divs) == 0:
        return f"{divs}\n0\n"

    # Get prime factors of n
    primes = []
    temp = n
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            primes.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primes.append(temp)

    if not primes:
        primes = [1]

    # Get prime factor set for each divisor
    div_to_primes = {}
    for d in divs:
        p_set = set()
        temp = d
        for p in primes:
            if temp % p == 0:
                p_set.add(p)
                while temp % p == 0:
                    temp //= p
        div_to_primes[d] = p_set

    # Build order: greedily find connections
    order = []
    visited = set()

    def gcd2(a, b):
        return gcd(a, b)

    # Greedy chain building
    start = min(divs)  # Start with smallest
    order.append(start)
    visited.add(start)
    current = start

    for _ in range(len(divs) - 1):
        found = False
        for candidate in divs:
            if candidate not in visited:
                # Check if shares prime factor with current
                p_curr = div_to_primes[current]
                p_cand = div_to_primes[candidate]
                common = p_curr & p_cand
                if common:
                    order.append(candidate)
                    visited.add(candidate)
                    current = candidate
                    found = True
                    break

        # If no direct connection, just pick any remaining
        if not found:
            for candidate in divs:
                if candidate not in visited:
                    order.append(candidate)
                    visited.add(candidate)
                    current = candidate
                    break

    # Count moves: adjacent coprime pairs in circular arrangement
    moves = 0
    nlen = len(order)
    for i in range(nlen):
        a = order[i]
        b = order[(i + 1) % nlen]
        if gcd2(a, b) == 1:
            moves += 1

    return f"{' '.join(map(str, order))}\n{moves}\n"

