import sys
from typing import List

SPF = []

def build_spf(limit):
    """Build smallest prime factor array up to limit."""
    global SPF
    SPF = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if SPF[i] == i:
            for j in range(i * i, limit + 1, i):
                if SPF[j] == j:
                    SPF[j] = i

def factorize(n):
    """Return prime factors of n using SPF."""
    factors = []
    while n > 1:
        if SPF[n] == n:
            factors.append(n)
            break
        else:
            p = SPF[n]
            factors.append(p)
            n //= p
    return factors

def get_divisors(factors):
