from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "IMPOSSIBLE\n"

    n, c = map(int, lines[0].split())

    if n <= 1:
        if c == 0:
            return "1\n"
        return "IMPOSSIBLE\n"

    # Build constraint graph
    # LEFT(a, b) means b comes before a in in-order traversal
    # RIGHT(a, b) means a comes before b in in-order traversal
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for line in lines[1:]:
        parts = line.split()
        if len(parts) < 3:
            continue
        try:
            a, b = int(parts[0]), int(parts[1])
            direction = parts[2].upper()

            if direction == "LEFT":
                adj[b].append(a)
                in_degree[a] += 1
            elif direction == "RIGHT":
                adj[a].append(b)
                in_degree[b] += 1
        except (ValueError, IndexError):
            continue

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If not all nodes are in result, there's a cycle
    if len(result) != n:
        return "IMPOSSIBLE\n"

    # Verify the topological order is valid: 
    # For any LEFT(a,b): b must precede a in result
    # For any RIGHT(a,b): a must precede b in result
    pos = {node: i for i, node in enumerate(result)}

    for line in lines[1:]:
        parts = line.split()
        if len(parts) < 3:
            continue
        try:
            a, b = int(parts[0]), int(parts[1])
            direction = parts[2].upper()

            if direction == "LEFT":
                if pos[b] >= pos[a]:
                    return "IMPOSSIBLE\n"
            elif direction == "RIGHT":
                if pos[a] >= pos[b]:
                    return "IMPOSSIBLE\n"
        except (ValueError, IndexError):
            continue

    return ' '.join(map(str, result)) + '\n'
