```python
def solution(s):
    """
    Find the lexicographically smallest good string with minimum length.
    A good string has all input strings as most frequent substrings.
    """
    lines = s.strip().split('\n')
    if not lines or (len(lines) == 1 and lines[0] == ''):
        return "NO\n"

    try:
        n = int(lines[0].strip())
    except ValueError:
        return "NO\n"

    if n < 1:
        return "NO\n"

    strings = []
    for i in range(1, len(lines)):
        line = lines[i].rstrip('\r\n')
        if line:
            strings.append(line)

    if len(strings) != n:
        return "NO\n"

    if any(len(st) == 0 for st in strings):
        return "NO\n"

    # Check for duplicates
    if len(set(strings)) != n:
        return "NO\n"

    num = len(strings)

    # Single string case
    if num == 1:
        return strings[0] + "\n"

    # Compute overlap: overlap[i][j] = longest suffix of i matching prefix of j
    overlap = [[0] * num for _ in range(num)]
    for i in range(num):
        for j in range(num):
            if i == j:
                overlap[i][j] = 0
            else:
                best = 0
                lm = min(len(strings[i]), len(strings[j]))
                for l in range(1, lm + 1):
                    if strings[i][-l:] == strings[j][:l]:
                        best = l
                overlap[i][j] = best

    # DP with bitmask for shortest superstring
    size = 1 << num
    INF = float('inf')
    dp = [[INF] * num for _ in range(size)]
    parent = [[[-1, -1]] * num for _ in range(size)]

    for i in range(num):
        dp[1 << i][i] = len(strings[i])

    # Fill DP table
    for mask in range(size):
        for last in range(num):
            if not ((mask >> last) & 1):
                continue
            if dp[mask][last] == INF:
                continue
            for nxt in range(num):
                if (mask >> nxt) & 1:
                    continue
                nm = mask | (1 << nxt)
                nm_cost = dp[mask][last] + len(strings[nxt]) - overlap[last][nxt]
                if nm_cost < dp[nm][nxt]:
                    dp[nm][nxt] = nm_cost
                    parent[nm][nxt] = [last, mask]

    full_mask = size - 1
    final_ans = min(dp[full_mask])

    if final_ans == INF:
        return "NO\n"

    best_str = None

    # Try all valid end positions and find lexicographically smallest
    for end in range(num):
        if dp[full_mask][end] == final_ans:
            # Reconstruct path
            path = []
            curr = end
            curr_mask = full_mask

            while True:
                path.append(curr)
                prev_i, prev_mask = parent[curr_mask][curr]
                if prev_i == -1:
                    break
                curr = prev_i
                curr_mask = prev_mask

            path.reverse()

            # Build superstring
            res = strings[path[0]]
            for i in range(1, len(path)):
                ov = overlap[path[i-1]][path[i]]
                res += strings[path[i]][len(strings[path[i]]) - ov:]

            # Verify all strings are substrings
            valid = all(st in res for st in strings)
            if valid:
                if best_str is None or res < best_str:
                    best_str = res

    return best_str + "\n" if best_str else "NO\n"
